parameters.jsCode:
const alert = $json.body.body;

return [{
  json: {
    file_path: alert.syscheck.path,
    md5: alert.syscheck.md5_after,
    sha1: alert.syscheck.sha1_after,
    sha256: alert.syscheck.sha256_after,
    agent: alert.agent.name,
    rule: alert.rule.description
  }
}];

if (!$json.data) {
  return [{
    json: {
      status: "not_found",
      subject: "[INFO] File Not Found In VirusTotal",
      html: `
      <div style="font-family:Arial,sans-serif;">
        <h2>VirusTotal has no information for this file.</h2>
      </div>
      `
    }
  }];
}

const stats = $json.data.attributes.last_analysis_stats;

const malicious = stats.malicious || 0;
const suspicious = stats.suspicious || 0;
const harmless = stats.harmless || 0;
const undetected = stats.undetected || 0;

let riskLevel = "LOW";

if (malicious >= 30) {
  riskLevel = "CRITICAL";
} else if (malicious >= 10) {
  riskLevel = "HIGH";
} else if (malicious >= 3) {
  riskLevel = "MEDIUM";
}

let severityColor = "#4CAF50";

if (riskLevel === "MEDIUM") {
  severityColor = "#FF9800";
} else if (riskLevel === "HIGH") {
  severityColor = "#F44336";
} else if (riskLevel === "CRITICAL") {
  severityColor = "#8B0000";
}

const ioc = $('Extract IOCs').first().json;

const html = `
<div style="font-family:Arial,sans-serif;max-width:900px;">

<h1 style="
background:#d32f2f;
color:white;
padding:15px;
margin:0;
">
🚨 Malware Detection Alert
</h1>

<br>

<h2>Incident Summary</h2>

<table border="1" cellpadding="10" cellspacing="0" width="100%">
<tr>
<td><b>Severity</b></td>
<td style="color:${severityColor};font-weight:bold;">
${riskLevel}
</td>
</tr>

<tr>
<td><b>Agent</b></td>
<td>${ioc.agent}</td>
</tr>

<tr>
<td><b>Detection Rule</b></td>
<td>${ioc.rule}</td>
</tr>

<tr>
<td><b>File Path</b></td>
<td>${ioc.file_path}</td>
</tr>
</table>

<br>

<h2>File Hash Information</h2>

<table border="1" cellpadding="10" cellspacing="0" width="100%">
<tr>
<td><b>MD5</b></td>
<td>${ioc.md5}</td>
</tr>

<tr>
<td><b>SHA1</b></td>
<td>${ioc.sha1}</td>
</tr>

<tr>
<td><b>SHA256</b></td>
<td>${ioc.sha256}</td>
</tr>
</table>

<br>

<h2>VirusTotal Analysis</h2>

<table border="1" cellpadding="10" cellspacing="0" width="100%">
<tr>
<td><b>Malicious Engines</b></td>
<td>${malicious}</td>
</tr>

<tr>
<td><b>Suspicious Engines</b></td>
<td>${suspicious}</td>
</tr>

<tr>
<td><b>Harmless Engines</b></td>
<td>${harmless}</td>
</tr>

<tr>
<td><b>Undetected Engines</b></td>
<td>${undetected}</td>
</tr>
</table>

<br>

<h2>Recommended Actions</h2>

<ul>
<li>Review the file source and execution history.</li>
<li>Investigate endpoint activity.</li>
<li>Perform IOC hunting across the environment.</li>
<li>Quarantine or remove the file if malicious.</li>
<li>Check for lateral movement or persistence mechanisms.</li>
</ul>

<br>

<a href="https://www.virustotal.com/gui/file/${ioc.sha256}"
style="
background:#1976d2;
color:white;
padding:12px 20px;
text-decoration:none;
border-radius:5px;
font-weight:bold;
">
Open VirusTotal Report
</a>

<br><br>

<hr>

<p style="color:gray;">
Generated automatically by Wazuh + n8n Security Automation Workflow
</p>

</div>
`;

return [{
  json: {
    status: "found",
    riskLevel,
    malicious,
    suspicious,
    harmless,
    undetected,

    file_path: ioc.file_path,
    md5: ioc.md5,
    sha1: ioc.sha1,
    sha256: ioc.sha256,

    agent: ioc.agent,
    rule: ioc.rule,

    html,

    subject: `[${riskLevel}] Malware Alert - ${ioc.agent}`
  }
}];

